const item = $input.first().json;
const body = item.body || item;
const page_id = String(body.page_id || body.facebook_page_id || (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0].value && body.entry[0].changes[0].value.page_id) || '').trim();
function normalizePhone(phone) {
  if (!phone) return '';
  const d = String(phone).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  return d ? '+1' + d : '';
}
const raw = [body.source, body.site, body.page_url, body.form_name, body.website].join(' ').toLowerCase();
let site = 'inconnu', projet = 'multi';
if (raw.includes('icithermopompe') || raw.includes('thermopompe')) { site = 'icithermopompe'; projet = 'thermopompe'; }
else if (raw.includes('isolationqc')) { site = 'isolationqc'; projet = 'isolation'; }
else if (raw.includes('portesetfenetres') || raw.includes('fenetres')) { site = 'portesetfenetresqc'; projet = 'portes_fenetres'; }
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const toronto = new Date(nowStr);
const hour = toronto.getHours();
const day = toronto.getDay();
const isBusinessHours = day >= 1 && day <= 6 && hour >= 8 && hour < 20;
return [{ json: {
  ...body,
  first_name: body.first_name || '',
  last_name: body.last_name || '',
  phone: normalizePhone(body.phone || body.mobile),
  email: body.email || '',
  lead_city: body.lead_city || body.city || '',
  current_heating: body.current_heating || body.chauffage_actuel || '',
  project_type: body.project_type || projet,
  energie_site_source: site,
  page_id,
  facebook_page_id: page_id,
  isBusinessHours,
  torontoHour: hour
}}];

const b = $('2 Site + Tel + Heures').first().json;
const token = '{{ENERGIE_WEBHOOK_TOKEN}}';
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/energie/lead',
  headers: { 'X-Energie-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: {
    first_name: b.first_name,
    last_name: b.last_name,
    phone: b.phone,
    email: b.email,
    city: b.lead_city,
    current_heating: b.current_heating,
    project_type: b.project_type,
    site: b.energie_site_source,
    page_id: b.page_id || b.facebook_page_id || '',
    form_id: b.form_id || b.leadgen_form_id || '',
    page_url: b.page_url || '',
    form_name: b.form_name || ''
  },
  json: true,
});
return [{ json: { ...b, ...res } }];

const b = $('2 Site + Tel + Heures').first().json;
const odoo = $('3 Odoo Create Lead').first().json;
const apiKey = '{{ELEVENLABS_API_KEY}}';
const agentId = odoo.elevenlabs_agent_id_energie || $env.ELEVENLABS_AGENT_ID_ENERGIE;
const phoneId = odoo.elevenlabs_phone_number_id || $env.ELEVENLABS_PHONE_NUMBER_ID_ENERGIE;
if (!agentId || !phoneId || !b.phone) {
  return [{ json: { ...odoo, error: 'missing_call_ids' } }];
}
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
  body: {
    agent_id: agentId,
    agent_phone_number_id: phoneId,
    to_number: b.phone,
    telephony_call_config: { ringing_timeout_secs: 25 },
    conversation_initiation_client_data: {
      dynamic_variables: {
        lead_name: b.first_name || 'there',
        lead_site: b.energie_site_source,
        lead_city: b.lead_city,
        current_heating: b.current_heating,
        project_type: b.project_type,
        lead_id_odoo: String(odoo.lead_id || '')
      }
    }
  },
  json: true,
});
return [{ json: { ...odoo, call: res } }];

const lead = $('3 Odoo Create Lead').first().json;
const prep = $('2 Site + Tel + Heures').first().json;
if (!lead.lead_id) return [];
const token = '{{ENERGIE_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/energie/lead/update',
  headers: { 'X-Energie-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: { lead_id: lead.lead_id, next_action: 'Appel matin programmé 8h Toronto (lead hors heures)' },
  json: true,
});
return [{ json: {
  pipeline: 'energie',
  lead_id: lead.lead_id,
  phone: prep.phone || lead.phone,
  first_name: prep.first_name,
  lead_city: prep.lead_city,
  current_heating: prep.current_heating,
  project_type: prep.project_type,
  energie_site_source: prep.energie_site_source,
  agent_id: lead.elevenlabs_agent_id_energie || lead.agent_id || '',
  elevenlabs_phone_number_id: lead.elevenlabs_phone_number_id || ''
}}];
